
/* No visible scrollbars on the landing box — it still scrolls by touch
   when content overflows a short screen (Amy 2026-08-25). */
.nge-mw-sheet { scrollbar-width: none; -ms-overflow-style: none;
}
.nge-mw-sheet::-webkit-scrollbar { display: none; width: 0; height: 0;
}

/* Spinnable cell: perspective stage; the glyph coin-spins on Y. */
.nge-mw-spin-stage {
  width: 76px;
  height: 64px;
  margin: 0 auto 2px;
  perspective: 320px;
  touch-action: none;
  cursor: grab;
}
.nge-mw-spin-stage:active { cursor: grabbing;
}
.nge-mw-spin {
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  will-change: transform;
  filter: drop-shadow(0 0 10px rgba(24, 207, 255, 0.35));
}

/* Fullscreen on phones: the sheet IS the landing page, not a box floating
   over one (Amy 2026-08-25). The blocker just hosts it edge to edge. */
.nge-mw-blocker {
  position: fixed;
  inset: 0;
  z-index: 10500;
  background: #070d1a;
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: 0;
  box-sizing: border-box;
}
.nge-mw-sheet {
  position: relative;
  width: 100%;
  max-width: 560px;
  height: 100dvh;
  max-height: 100dvh;
  overflow-y: auto;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  padding: calc(8px + env(safe-area-inset-top)) 18px calc(10px + env(safe-area-inset-bottom));
  border-radius: 0;
  border: none;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(53, 181, 255, 0.10), transparent 60%),
    linear-gradient(180deg, #0b1424 0%, #070d1a 100%);
  color: #dfe9ff;
  font-family: 'Roboto', sans-serif;
}

/* Vertically center the content on tall screens without clipping short
   ones: auto margins inside a scroll container collapse safely. */
.nge-mw-body { margin-top: auto; margin-bottom: auto;
}
.nge-mw-handle {
  width: 42px;
  height: 4px;
  border-radius: 2px;
  margin: 2px auto 8px;
  background: rgba(53, 181, 255, 0.4);
  box-shadow: 0 0 8px rgba(53, 181, 255, 0.35);
}
.nge-mw-close {
  position: absolute;
  top: 10px;
  right: 8px;
  width: 40px;
  height: 40px;
  background: none;
  border: none;
  color: rgba(159, 180, 216, 0.8);
  font-size: 24px;
  cursor: pointer;
  line-height: 1;
}
.nge-mw-kicker {
  font-family: 'Orbitron', sans-serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 2.2px;
  color: rgba(53, 181, 255, 0.85);
  text-shadow: 0 0 8px rgba(53, 181, 255, 0.45);
  margin: 2px 0 4px;
}
.nge-mw-title {
  font-family: 'Orbitron', sans-serif;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #f0f6ff;
  margin: 0 0 6px;
}
.nge-mw-copy {
  font-size: 13.5px;
  line-height: 1.45;
  color: #aebfdd;
  margin: 0 0 12px;
}

/* Systems list: pure typography, no chrome. These are not buttons, they
   describe what unlocks after login. */
.nge-mw-sys-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
  margin-bottom: 2px;
  padding: 2px 2px 0;
}
.nge-mw-sys {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}
.nge-mw-sys-icon {
  font-size: 20px;
  line-height: 1.2;
  flex: 0 0 auto;
  filter: drop-shadow(0 0 6px rgba(53, 181, 255, 0.35));
}
.nge-mw-neuron-icon {
  width: 30px;
  height: 30px;
  vertical-align: middle;
  filter:
    drop-shadow(0 0 5px rgba(53, 181, 255, 0.9))
    drop-shadow(0 0 12px rgba(53, 181, 255, 0.5))
    brightness(1.15);
}
.nge-mw-sys-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.nge-mw-sys-label {
  font-family: 'Orbitron', sans-serif;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.8px;
  color: #dfeeff;
  text-shadow: 0 0 10px rgba(53, 181, 255, 0.35);
}
.nge-mw-sys-sub {
  font-size: 11px;
  color: #8fa6cc;
  line-height: 1.35;
}

/* Logged in: the rows are live links into their panels. */
.nge-mw-sys--link {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-align: left;
  font: inherit;
  color: inherit;
}
.nge-mw-sys--link .nge-mw-sys-label {
  color: rgb(53, 181, 255);
  text-shadow: 0 0 10px rgba(53, 181, 255, 0.5);
}
.nge-mw-sys--link:active .nge-mw-sys-label {
  text-shadow: 0 0 16px rgba(53, 181, 255, 0.9);
}
.nge-mw-sys-go {
  font-family: inherit;
  opacity: 0.8;
}

/* Divider */
.nge-mw-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 11px 0 8px;
}
.nge-mw-divider::before,
.nge-mw-divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(53, 181, 255, 0.35), transparent);
}
.nge-mw-divider span {
  font-family: 'Orbitron', sans-serif;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 1.8px;
  color: rgba(143, 166, 204, 0.85);
  white-space: nowrap;
}

/* Learn rows */
.nge-mw-learn {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  box-sizing: border-box;
  padding: 9px 12px;
  margin-bottom: 7px;
  border-radius: 10px;
  background: rgba(9, 17, 32, 0.8);
  border: 1px solid rgba(53, 181, 255, 0.22);
  color: #eaf3ff;
  cursor: pointer;
  text-align: left;
}
.nge-mw-learn:active { border-color: rgba(53, 181, 255, 0.6);
}
.nge-mw-learn-icon { font-size: 24px;
}
.nge-mw-learn-icon--svg { display: inline-flex; align-items: center; justify-content: center;
}
.nge-mw-net {
  width: 26px; height: 26px; display: block;
  filter: drop-shadow(0 0 5px rgba(24, 207, 255, 0.55));
}
.nge-mw-learn-text {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
  min-width: 0;
}
.nge-mw-learn-title {
  font-family: 'Orbitron', sans-serif;
  font-size: 13px;
  font-weight: 600;
}
.nge-mw-learn-sub {
  font-size: 11px;
  color: #8fa6cc;
}
.nge-mw-learn-arrow {
  font-size: 22px;
  color: rgba(53, 181, 255, 0.8);
}

/* Share row */
.nge-mw-share {
  display: flex;
  gap: 10px;
}
.nge-mw-share button {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 40px;
  border-radius: 9px;
  background: rgba(9, 17, 32, 0.8);
  border: 1px solid rgba(53, 181, 255, 0.28);
  color: #cfe2ff;
  font-family: 'Orbitron', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.8px;
  cursor: pointer;
}
.nge-mw-share button:active {
  border-color: rgba(53, 181, 255, 0.65);
  box-shadow: 0 0 12px rgba(53, 181, 255, 0.3);
}

/* Bypass + CTA */
.nge-mw-bypass {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 8px 4px 2px;
  background: none;
  border: none;
  color: rgba(143, 166, 204, 0.75);
  font-family: 'Orbitron', sans-serif;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 1.1px;
  white-space: nowrap;
  cursor: pointer;
}
.nge-mw-bypass:active { color: rgb(53, 181, 255);
}
.nge-mw-tour-link { margin-top: 0; padding-top: 2px; color: rgba(53, 181, 255, 0.8);
}
.nge-mw-cta {
  display: block;
  width: 100%;
  margin-top: 11px;
  padding: 11px;
  border-radius: 9px;
  background: linear-gradient(180deg, rgba(53, 181, 255, 0.22), rgba(53, 181, 255, 0.08));
  border: 1px solid rgba(53, 181, 255, 0.55);
  color: #eaf6ff;
  font-family: 'Orbitron', sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.4px;
  cursor: pointer;
  box-shadow: 0 0 16px rgba(53, 181, 255, 0.18), inset 0 0 14px rgba(53, 181, 255, 0.08);
}
.nge-mw-cta:active { box-shadow: 0 0 22px rgba(53, 181, 255, 0.4);
}
.nge-mw-invite {
  font-size: 12.5px;
  line-height: 1.45;
  color: #aebfdd;
  margin: 0;
}
.nge-mw-cta-sub {
  margin-top: 6px;
  text-align: center;
  font-family: 'Orbitron', sans-serif;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 1.4px;
  color: rgba(143, 166, 204, 0.75);
}

/* Pre-check: quiet placeholder where the login section will land. Sized
   like the signed-in row so the sheet doesn't jump when the check settles. */
.nge-mw-verifying {
  display: block;
  width: 100%;
  box-sizing: border-box;
  margin-top: 11px;
  padding: 11px;
  border-radius: 9px;
  border: 1px solid rgba(53, 181, 255, 0.18);
  text-align: center;
  color: rgba(143, 166, 204, 0.7);
  font-family: 'Orbitron', sans-serif;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 1.6px;
  animation: nge-mw-verify-pulse 1.4s ease-in-out infinite;
}
@keyframes nge-mw-verify-pulse {
0%, 100% { opacity: 0.55;
}
50%      { opacity: 1;
}
}

/* Logged in: status row in the invite's place; tap opens the profile. */
.nge-mw-signed {
  display: block;
  width: 100%;
  margin-top: 11px;
  padding: 10px;
  border-radius: 9px;
  background: rgba(0, 220, 120, 0.06);
  border: 1px solid rgba(0, 220, 120, 0.35);
  color: #b8f5d8;
  font-family: 'Orbitron', sans-serif;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 1.2px;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nge-mw-signed:active { box-shadow: 0 0 16px rgba(0, 220, 120, 0.3);
}

/* Sheet transition */
.nge-mw-enter-active,
.nge-mw-leave-active { transition: opacity 0.28s ease;
}
.nge-mw-enter-active .nge-mw-sheet,
.nge-mw-leave-active .nge-mw-sheet { transition: transform 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}
.nge-mw-enter-from,
.nge-mw-leave-to { opacity: 0;
}
.nge-mw-enter-from .nge-mw-sheet,
.nge-mw-leave-to .nge-mw-sheet { transform: translateY(60px);
}
