
/* Armed (T held): the panel glows and the page cursor becomes a crosshair,
   so there is no doubt the next click drops a tag. */
body.nge-tag-armed { cursor: crosshair;
}
.nge-tagmode-wrap--armed .nge-tagmode[data-v-1edf93ef] {
  border-color: rgba(245, 209, 66, 0.85);
  box-shadow: 0 6px 28px rgba(0, 0, 0, 0.55), 0 0 18px rgba(245, 209, 66, 0.35);
}
.nge-tagmode-wrap[data-v-1edf93ef] {
  position: fixed;
  z-index: 10005;
  width: 340px;
  max-width: calc(100vw - 24px);
}

/* ── The box. Materialize ported verbatim from scifi-ui hologram.css:
      "it arrives blurred, overbright and slightly too large, and settles
      through a soft overshoot at 60 per cent". The reverse plays the same
      curve backwards for the swap. ── */
.nge-tagmode[data-v-1edf93ef] {
  position: relative;
  max-height: calc(100vh - 90px);
  overflow-y: auto;
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba(6, 10, 20, 0.95);
  border: 1px solid rgba(245, 209, 66, 0.35);
  box-shadow: 0 6px 28px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(245, 209, 66, 0.08);
  backdrop-filter: blur(8px);
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  animation: nge-holo-materialize-1edf93ef 0.8s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.nge-holo-out[data-v-1edf93ef] {
  animation: nge-holo-materialize-1edf93ef 0.5s cubic-bezier(0.16, 1, 0.3, 1) reverse both;
}
/* Expanding from the slim strip: the pop-in materialize is suppressed and
   the beam acts as a mask, a clip-path driven from the draw's progress
   unrolls the finished box downward in step with the light. */
.nge-tagmode--drawing[data-v-1edf93ef] {
  animation: none;
}
/* Success box while the burst particles are still carrying its border. */
/* While the streams are still charging: dim body, no pop-in animation.
   The beams phase clears this and the body eases in with the light. */
.nge-tagmode--building[data-v-1edf93ef] {
  animation: none;
  opacity: 0.14;
  transform: scale(0.985);
}
.nge-tagmode--success[data-v-1edf93ef] { transition: opacity 0.45s ease, transform 0.45s ease;
}
/* The send-off: scifi-ui's holodialog-materialize played in reverse, the
   box blooms bright, blurs, and lifts away (exact keyframe values from
   hologram.css, order mirrored). The beam then draws the form back in. */
.nge-tagmode--spinout[data-v-1edf93ef] {
  animation: nge-dematerialize-1edf93ef 0.42s cubic-bezier(0.7, 0, 0.84, 0.16) both !important;
  pointer-events: none;
}
@keyframes nge-dematerialize-1edf93ef {
0%   { opacity: 1; transform: scale(1) translateY(0); filter: blur(0) brightness(1);
}
40%  { opacity: 1; transform: scale(0.99); filter: blur(0) brightness(1.1);
}
70%  { opacity: 0.6; filter: blur(3px) brightness(1.5);
}
100% { opacity: 0; transform: scale(1.04) translateY(-10px); filter: blur(20px) brightness(3);
}
}
.nge-tagmode--frameless[data-v-1edf93ef] {
  border-color: transparent !important;
  box-shadow: none !important;
}
.nge-tagmode > *[data-v-1edf93ef] { transition: opacity 0.28s ease;
}
.nge-tagmode[data-v-1edf93ef] { transition: border-color 0.3s ease, box-shadow 0.3s ease, background 0.3s ease;
}
/* Softened from the scifi-ui original: the brightness(3) overbright flash
   read as an error strobe on a large panel (Amy). Keep the blur settle and
   the soft overshoot; drop the flash. Oddly satisfying, not alarming. */
@keyframes nge-holo-materialize-1edf93ef {
0%   { opacity: 0; transform: scale(1.025) translateY(-8px); filter: blur(14px);
}
60%  { opacity: 1; transform: scale(0.995); filter: blur(0);
}
100% { opacity: 1; transform: scale(1) translateY(0); filter: blur(0);
}
}
@media (prefers-reduced-motion: reduce) {
.nge-tagmode[data-v-1edf93ef], .nge-holo-out[data-v-1edf93ef] { animation: none;
}
}
.nge-tagmode-head[data-v-1edf93ef] { display: flex; align-items: center; cursor: grab;
}
.nge-tagmode-head[data-v-1edf93ef]:active { cursor: grabbing;
}
.nge-tagmode-pin[data-v-1edf93ef] { display: inline-flex; vertical-align: -2px;
}
.nge-tagmode-pin svg[data-v-1edf93ef] { filter: drop-shadow(0 0 4px rgba(53, 181, 255, 0.55));
}

/* ── Collapsed corner strip ── */
.nge-tagmode-mini[data-v-1edf93ef] {
  position: relative;
  display: flex;
  align-items: center;
  gap: 4px;
  /* The wrap is 340px for the full panel; the strip sizes to its own
     content so the border always encloses every button (Amy: the x and
     the hand were poking out of the box). */
  width: max-content;
  max-width: calc(100vw - 24px);
  /* Extra room on the right so the cursor has somewhere calm to land. */
  padding: 5px 14px 5px 7px;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(4, 6, 14, 0.94) 0%, rgba(8, 12, 24, 0.92) 100%);
  border: 1px solid rgba(53, 181, 255, 0.35);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.5), 0 0 12px rgba(53, 181, 255, 0.12);
  backdrop-filter: blur(8px);
}
.nge-tagmode-mini-grip[data-v-1edf93ef] {
  display: inline-flex;
  cursor: grab;
  padding: 2px 3px;
  font-size: 14px;
  user-select: none;
}
.nge-tagmode-mini-grip[data-v-1edf93ef]:active { cursor: grabbing;
}
.nge-tagmode-mini-chip[data-v-1edf93ef] {
  font-family: 'Orbitron', 'Inter', sans-serif;
  font-size: 10px;
  letter-spacing: 0.06em;
  padding: 4px 8px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.04);
  color: #cfe3ff;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 3px;
}
.nge-tagmode-mini-chip--active[data-v-1edf93ef] {
  border-color: rgba(53, 181, 255, 0.8);
  background: rgba(53, 181, 255, 0.14);
  color: #fff;
  box-shadow: 0 0 8px rgba(53, 181, 255, 0.25);
}
.nge-tagmode-mini-act[data-v-1edf93ef] {
  font-size: 13px;
  line-height: 1;
  padding: 4px 7px;
  border-radius: 7px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.04);
  color: #cfe3ff;
  cursor: pointer;
}
.nge-tagmode-mini-act--on[data-v-1edf93ef] {
  border-color: rgba(53, 181, 255, 0.9);
  background: rgba(53, 181, 255, 0.2);
  animation: nge-arm-pulse-1edf93ef 1.1s ease-in-out infinite;
}
.nge-tagmode-mini-close[data-v-1edf93ef] { color: #a8b6cf;
}
.nge-tagmode-mini-close[data-v-1edf93ef]:hover { color: #fff; border-color: rgba(224, 96, 96, 0.5); background: rgba(224, 96, 96, 0.12);
}
.nge-tagmode-mini-hand[data-v-1edf93ef] {
  display: inline-flex;
  margin-left: 2px;
  padding: 3px 4px;
  color: #8ea3c4;
  cursor: grab;
  user-select: none;
}
.nge-tagmode-mini-hand[data-v-1edf93ef]:hover { color: #cfe3ff;
}
.nge-tagmode-mini-hand[data-v-1edf93ef]:active { cursor: grabbing;
}
.nge-tagmode-mini-submit[data-v-1edf93ef] { color: #7dffb0; border-color: rgba(125, 255, 176, 0.35);
}
.nge-tagmode-mini-submit[data-v-1edf93ef]:hover { background: rgba(125, 255, 176, 0.12);
}
.nge-tagmode-mini-act[data-v-1edf93ef]:disabled { opacity: 0.5; cursor: default;
}
.nge-tagmode-flash--mini[data-v-1edf93ef] {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  white-space: nowrap;
}
.nge-tagmode-pos--pending b[data-v-1edf93ef] { color: #35b5ff;
}

/* "coordinates:" label with the values small on one line beneath. */
.nge-tagmode-coords[data-v-1edf93ef] { display: flex; flex-direction: column; gap: 1px; min-width: 0;
}
.nge-tagmode-coords-label[data-v-1edf93ef] {
  font-family: 'Orbitron', 'Inter', sans-serif;
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(160, 185, 220, 0.75);
}
.nge-tagmode-coords-vals[data-v-1edf93ef] {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  white-space: nowrap;
  color: #cfe0f5;
}
.nge-tagmode-coords-vals b[data-v-1edf93ef] { font-weight: 600; color: #e9c46a;
}
.nge-tagmode-pos--pending .nge-tagmode-coords-vals b[data-v-1edf93ef] { color: #35b5ff;
}
.nge-tagmode-copy[data-v-1edf93ef] {
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 5px;
  color: #8ea3c4;
  font-size: 12px;
  line-height: 1;
  padding: 2px 5px;
  cursor: pointer;
  transition: color 0.12s, border-color 0.12s;
}
.nge-tagmode-copy[data-v-1edf93ef]:hover { color: #d8ecff; border-color: rgba(53, 181, 255, 0.5);
}
.nge-tagmode-title[data-v-1edf93ef] {
  flex: 1;
  font-family: 'Orbitron', 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  color: #f5d142;
  user-select: none;
}
.nge-tagmode-close[data-v-1edf93ef] {
  background: none; border: none; color: #889; font-size: 18px;
  line-height: 1; cursor: pointer; padding: 0 2px;
}
.nge-tagmode-close[data-v-1edf93ef]:hover { color: #fff;
}
.nge-tagmode-hint[data-v-1edf93ef] { font-size: 11px; color: rgba(255, 255, 255, 0.55); line-height: 1.45;
}
.nge-tagmode-hint b[data-v-1edf93ef] { color: #f5d142; font-weight: 600;
}
.nge-tagmode-chips[data-v-1edf93ef] { display: flex; flex-wrap: wrap; gap: 6px;
}
.nge-tagmode-chip[data-v-1edf93ef] {
  padding: 5px 12px;
  border-radius: 12px;
  font-size: 12.5px;
  cursor: pointer;
  background: rgba(245, 209, 66, 0.06);
  border: 1px solid rgba(245, 209, 66, 0.28);
  color: #dcb;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
/* Type colors match the light: blue Cut, green Extend, purple Other. */
.nge-tagmode-chip--cut[data-v-1edf93ef] { background: rgba(53, 181, 255, 0.08); border-color: rgba(53, 181, 255, 0.35); color: #9fd6ff;
}
.nge-tagmode-chip--cut.nge-tagmode-chip--active[data-v-1edf93ef] { background: rgba(53, 181, 255, 0.2); border-color: rgba(53, 181, 255, 0.75); color: #d8efff;
}
.nge-tagmode-chip--ext[data-v-1edf93ef] { background: rgba(96, 224, 128, 0.08); border-color: rgba(96, 224, 128, 0.32); color: #9fe8b0;
}
.nge-tagmode-chip--ext.nge-tagmode-chip--active[data-v-1edf93ef] { background: rgba(96, 224, 128, 0.2); border-color: rgba(96, 224, 128, 0.7); color: #d9ffe3;
}
.nge-tagmode-chip--other[data-v-1edf93ef] { background: rgba(200, 150, 255, 0.08); border-color: rgba(200, 150, 255, 0.32); color: #d9bdfa;
}
.nge-tagmode-chip--other.nge-tagmode-chip--active[data-v-1edf93ef] { background: rgba(200, 150, 255, 0.2); border-color: rgba(200, 150, 255, 0.7); color: #f0e2ff;
}
.nge-tagmode-chip-img[data-v-1edf93ef] { width: 15px; height: 15px; vertical-align: -3px; margin-right: 3px;
}
.nge-tagmode-chip--active[data-v-1edf93ef] {
  background: rgba(245, 209, 66, 0.18);
  border-color: rgba(245, 209, 66, 0.65);
  color: #ffe9a0;
}
.nge-tagmode-note[data-v-1edf93ef] {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  color: #dde;
  font-size: 12px;
  padding: 6px 9px;
}
.nge-tagmode-note[data-v-1edf93ef]:focus { outline: none; border-color: rgba(245, 209, 66, 0.45);
}
.nge-tagmode-extras[data-v-1edf93ef] { display: flex; gap: 8px;
}
.nge-tagmode-select[data-v-1edf93ef] {
  flex: 1;
  min-width: 0;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  color: #dde;
  font-size: 11.5px;
  padding: 5px 7px;
  color-scheme: dark;
}
.nge-tagmode-shot[data-v-1edf93ef] {
  background: rgba(120, 140, 255, 0.1);
  border: 1px solid rgba(120, 140, 255, 0.3);
  border-radius: 6px;
  color: #bcd;
  font-size: 11.5px;
  padding: 5px 10px;
  cursor: pointer;
  white-space: nowrap;
}
.nge-tagmode-shot[data-v-1edf93ef]:hover { background: rgba(120, 140, 255, 0.2);
}
.nge-tagmode-foot[data-v-1edf93ef] { display: flex; align-items: center; gap: 8px;
}
.nge-tagmode-actions-row[data-v-1edf93ef] { display: flex; gap: 8px;
}
.nge-tagmode-arm[data-v-1edf93ef] {
  flex: 1;
  padding: 7px 10px;
  border-radius: 7px;
  font-size: 12px;
  cursor: pointer;
  background: rgba(120, 140, 255, 0.1);
  border: 1px solid rgba(120, 140, 255, 0.35);
  color: #cdf;
  white-space: nowrap;
}
.nge-tagmode-arm--on[data-v-1edf93ef] {
  background: rgba(245, 209, 66, 0.18);
  border-color: rgba(245, 209, 66, 0.65);
  color: #ffe9a0;
  animation: nge-arm-pulse-1edf93ef 1.2s ease-in-out infinite;
}
@keyframes nge-arm-pulse-1edf93ef {
0%, 100% { box-shadow: 0 0 0 0 rgba(245, 209, 66, 0.25);
}
50%      { box-shadow: 0 0 0 5px rgba(245, 209, 66, 0.06);
}
}
.nge-tagmode-pos[data-v-1edf93ef] { flex: 1; font-size: 11px; color: rgba(255, 255, 255, 0.65);
}
.nge-tagmode-pos b[data-v-1edf93ef] { color: #ffb454; font-weight: 600;
}
.nge-tagmode-btn[data-v-1edf93ef] {
  padding: 6px 12px;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  background: rgba(245, 209, 66, 0.14);
  border: 1px solid rgba(245, 209, 66, 0.45);
  color: #ffe9a0;
}
.nge-tagmode-btn[data-v-1edf93ef]:hover { background: rgba(245, 209, 66, 0.24);
}
.nge-tagmode-btn[data-v-1edf93ef]:disabled { opacity: 0.5; cursor: default;
}
/* The flash is a holo pill now, not a bare yellow string. */
.nge-tagmode-flash[data-v-1edf93ef] {
  align-self: center;
  font-family: 'Orbitron', 'Inter', sans-serif;
  font-size: 10.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #cfe9ff;
  background: rgba(6, 12, 24, 0.9);
  border: 1px solid rgba(53, 181, 255, 0.45);
  border-radius: 999px;
  padding: 5px 14px;
  box-shadow: 0 0 14px rgba(53, 181, 255, 0.2), inset 0 0 10px rgba(53, 181, 255, 0.07);
  animation: nge-flash-in-1edf93ef 0.25s cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes nge-flash-in-1edf93ef {
0%   { opacity: 0; transform: translateY(4px) scale(0.96);
}
100% { opacity: 1; transform: translateY(0) scale(1);
}
}

/* ── Success box ── */
.nge-tagmode--success[data-v-1edf93ef] {
  align-items: center;
  /* Matches the form box's measured footprint (successSize), so include
     border and padding in that width or the right edge walks off. */
  box-sizing: border-box;
  justify-content: center;
  gap: 10px;
  padding: 20px 16px;
  cursor: pointer;
  /* No border on the celebration box (Amy). Transparent, not none, so the
     measured footprint from successSize still lines up. */
  border-color: transparent;
}
/* Crossed scythes (Amy's render), the Scythes' crest on a logged tag. */
.nge-tagmode-success-scythes[data-v-1edf93ef] {
  width: 150px;
  height: 150px;
  object-fit: contain;
  filter: drop-shadow(0 0 10px rgba(176, 136, 255, 0.55));
}
.nge-tagmode-success-title[data-v-1edf93ef] {
  font-family: 'Orbitron', 'Inter', sans-serif;
  font-size: 13px;
  letter-spacing: 0.1em;
  color: #dff1ff;
  text-shadow: 0 0 12px rgba(53, 181, 255, 0.45);
}
.nge-tagmode-success-pos[data-v-1edf93ef] { font-size: 11.5px; color: rgba(158, 205, 255, 0.75);
}
.nge-tagmode-success-hint[data-v-1edf93ef] { font-size: 10.5px; color: rgba(255, 255, 255, 0.45); margin-top: 4px;
}

