0%   { background-position: 0 0, 0 0, 0 0;
}
100% { background-position: 60px 104px, -60px 104px, 0 104px;
}
}

/* Prismatic rays radiating from center — Bifrost feel, gold/cyan dominant */
.nge-batch-rays[data-v-b7713b13] {
  position: absolute;
  inset: 0;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
}
.nge-batch-ray[data-v-b7713b13] {
  position: absolute;
  width: 2px;
  height: 140vh;
  top: 50%;
  left: 50%;
  transform-origin: center;
  transform: translate(-50%, -50%) rotate(calc(var(--i) * 45deg));
  background: linear-gradient(to bottom, transparent 0%, var(--ray-color, rgba(255, 200, 80, 0.5)) 50%, transparent 100%);
  filter: blur(0.5px);
  opacity: 0;
  animation: nge-batch-ray-pulse-b7713b13 7s ease-in-out infinite;
  animation-delay: calc(var(--i) * 0.35s);
}
.nge-batch-ray[data-v-b7713b13]:nth-child(odd)  { --ray-color: rgba(255, 200, 80, 0.55);
}
.nge-batch-ray[data-v-b7713b13]:nth-child(even) { --ray-color: rgba(120, 200, 255, 0.5);
}
.nge-batch-ray[data-v-b7713b13]:nth-child(3) { --ray-color: rgba(255, 230, 180, 0.6);
}
.nge-batch-ray[data-v-b7713b13]:nth-child(7) { --ray-color: rgba(180, 230, 255, 0.55);
}
@keyframes nge-batch-ray-pulse-b7713b13 {
0%, 100% { opacity: 0;
}
40%, 60% { opacity: 0.5;
}
}

/* Shockwave — single expanding ring on entry */
.nge-batch-shockwave[data-v-b7713b13] {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100px;
  height: 100px;
  border: 2px solid rgba(120, 200, 255, 0.8);
  border-radius: 50%;
  transform: translate(-50%, -50%) scale(0);
  pointer-events: none;
  animation: nge-batch-shockwave-fire-b7713b13 1.4s ease-out 0.1s 1 forwards;
  box-shadow: 0 0 40px rgba(120, 200, 255, 0.6);
}
.nge-batch-shockwave--2[data-v-b7713b13] {
  border-color: rgba(255, 200, 80, 0.7);
  box-shadow: 0 0 40px rgba(255, 200, 80, 0.5);
  animation-delay: 0.4s;
  animation-duration: 1.6s;
}
@keyframes nge-batch-shockwave-fire-b7713b13 {
0%   { transform: translate(-50%, -50%) scale(0);  opacity: 1;
}
100% { transform: translate(-50%, -50%) scale(20); opacity: 0;
}
}

/* Card border ornaments — Asgardian gold corner brackets */
.nge-batch-corner[data-v-b7713b13] {
  position: absolute;
  width: 28px;
  height: 28px;
  pointer-events: none;
}
.nge-batch-corner[data-v-b7713b13]::before, .nge-batch-corner[data-v-b7713b13]::after {
  content: '';
  position: absolute;
  background: linear-gradient(135deg, rgba(255, 220, 130, 0.95), rgba(255, 180, 60, 0.6));
  box-shadow: 0 0 8px rgba(255, 200, 80, 0.6);
}
.nge-batch-corner[data-v-b7713b13]::before { width: 28px; height: 2px;
}
.nge-batch-corner[data-v-b7713b13]::after  { width: 2px;  height: 28px;
}
.nge-batch-corner--tl[data-v-b7713b13] { top: -1px; left: -1px;
}
.nge-batch-corner--tl[data-v-b7713b13]::before { top: 0;   left: 0;
}
.nge-batch-corner--tl[data-v-b7713b13]::after  { top: 0;   left: 0;
}
.nge-batch-corner--tr[data-v-b7713b13] { top: -1px; right: -1px;
}
.nge-batch-corner--tr[data-v-b7713b13]::before { top: 0;   right: 0;
}
.nge-batch-corner--tr[data-v-b7713b13]::after  { top: 0;   right: 0;
}
.nge-batch-corner--bl[data-v-b7713b13] { bottom: -1px; left: -1px;
}
.nge-batch-corner--bl[data-v-b7713b13]::before { bottom: 0; left: 0;
}
.nge-batch-corner--bl[data-v-b7713b13]::after  { bottom: 0; left: 0;
}
.nge-batch-corner--br[data-v-b7713b13] { bottom: -1px; right: -1px;
}
.nge-batch-corner--br[data-v-b7713b13]::before { bottom: 0; right: 0;
}
.nge-batch-corner--br[data-v-b7713b13]::after  { bottom: 0; right: 0;
}

/* Vertical scanline that sweeps across the card once on entry */
.nge-batch-scanline[data-v-b7713b13] {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(to bottom,
    transparent 0%,
    rgba(120, 200, 255, 0.9) 30%,
    rgba(255, 230, 180, 1) 50%,
    rgba(120, 200, 255, 0.9) 70%,
    transparent 100%);
  box-shadow: 0 0 12px rgba(120, 200, 255, 0.8), 0 0 24px rgba(120, 200, 255, 0.4);
  left: -10px;
  pointer-events: none;
  animation: nge-batch-scanline-sweep-b7713b13 1.8s ease-out 0.4s 1 forwards;
  opacity: 0;
}
@keyframes nge-batch-scanline-sweep-b7713b13 {
0%   { left: -10px; opacity: 0;
}
10%  { opacity: 1;
}
90%  { opacity: 1;
}
100% { left: calc(100% + 10px); opacity: 0;
}
}

/* X close button — gold accent, subtle until hover */
.nge-batch-close[data-v-b7713b13] {
  position: absolute;
  top: 12px;
  right: 14px;
  background: rgba(255, 200, 80, 0.08);
  border: 1px solid rgba(255, 200, 80, 0.25);
  color: rgba(255, 220, 130, 0.85);
  font-size: 1.4em;
  font-weight: 300;
  width: 32px;
  height: 32px;
  line-height: 1;
  cursor: pointer;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  z-index: 10;
  transition: all 0.18s;
  font-family: inherit;
}
.nge-batch-close[data-v-b7713b13]:hover {
  background: rgba(255, 200, 80, 0.2);
  border-color: rgba(255, 220, 130, 0.7);
  color: #ffe;
  box-shadow: 0 0 16px rgba(255, 200, 80, 0.5);
  transform: scale(1.1) rotate(90deg);
}

/* Nurro wrapper — holds the avatar + the orbiting runes */
.nge-batch-nurro-wrap[data-v-b7713b13] {
  position: relative;
  width: 92px;
  height: 92px;
  margin: 0 auto 22px;
}
.nge-batch-nurro-wrap .nge-batch-nurro[data-v-b7713b13] {
  margin: 0;
}

/* Orbiting Norse runes around the nurro */
.nge-batch-runes[data-v-b7713b13] {
  position: absolute;
  inset: 0;
  pointer-events: none;
  animation: nge-batch-runes-orbit-b7713b13 32s linear infinite;
}
@keyframes nge-batch-runes-orbit-b7713b13 {
0%   { transform: rotate(0);
}
100% { transform: rotate(360deg);
}
}
.nge-batch-rune[data-v-b7713b13] {
  position: absolute;
  top: 50%;
  left: 50%;
  --angle: calc(var(--i) * 60deg);
  /* place on a circle of radius 90 around the nurro center, then counter-rotate
     so the rune itself stays upright as the container spins */
  transform:
    translate(-50%, -50%)
    rotate(var(--angle))
    translateY(-90px)
    rotate(calc(-1 * var(--angle)));
  font-size: 1.4em;
  font-weight: 600;
  color: rgba(255, 220, 130, 0.85);
  text-shadow:
    0 0 10px rgba(255, 200, 80, 0.85),
    0 0 22px rgba(255, 180, 60, 0.5);
  animation: nge-batch-rune-pulse-b7713b13 3.4s ease-in-out infinite;
  animation-delay: calc(var(--i) * 0.45s);
}
@keyframes nge-batch-rune-pulse-b7713b13 {
0%, 100% { opacity: 0.4; filter: blur(0);
}
50%      { opacity: 1;   filter: blur(0.4px);
}
}
