
/* ── Floating container ── */
.nge-chat-float[data-v-1ed9098a] {
  position: fixed;
  bottom: 36px;
  left: 8px;
  z-index: 9000;
  display: flex;
  flex-direction: column;
  background: rgba(6, 10, 20, 0.85);
  border-radius: 6px;
  border: 1px solid rgba(74, 158, 255, 0.08);
  overflow: hidden;
  font-family: 'Inter', 'Roboto', sans-serif;
}
.nge-chat-float--collapsed[data-v-1ed9098a] {
  width: auto !important;
  height: auto !important;
  background: rgba(10, 14, 24, 0.6);
}
.nge-chat-float--dragging[data-v-1ed9098a] {
  user-select: none;
}

/* ── Resize handles ── */
.nge-chat-resize[data-v-1ed9098a] { position: absolute; z-index: 10;
}
.nge-chat-resize--corner[data-v-1ed9098a] {
  top: 0; left: 0;
  width: 14px; height: 14px;
  cursor: nw-resize;
}
.nge-chat-resize--corner[data-v-1ed9098a]::after {
  content: '';
  position: absolute;
  top: 3px; left: 3px;
  width: 6px; height: 6px;
  border-top: 2px solid rgba(74, 158, 255, 0.25);
  border-left: 2px solid rgba(74, 158, 255, 0.25);
  border-radius: 1px;
  transition: border-color 0.15s;
}
.nge-chat-resize--corner[data-v-1ed9098a]:hover::after {
  border-color: rgba(74, 158, 255, 0.6);
}
.nge-chat-resize--top[data-v-1ed9098a] {
  top: 0; left: 14px; right: 0;
  height: 4px;
  cursor: n-resize;
}
.nge-chat-resize--top[data-v-1ed9098a]:hover { background: rgba(74, 158, 255, 0.15);
}
.nge-chat-resize--right[data-v-1ed9098a] {
  top: 0; right: 0;
  width: 4px; bottom: 0;
  cursor: e-resize;
}
.nge-chat-resize--right[data-v-1ed9098a]:hover { background: rgba(74, 158, 255, 0.15);
}

/* ── Tiny control strip (drag handle + buttons) ── */
.nge-chat-strip[data-v-1ed9098a] {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  cursor: grab;
  user-select: none;
  flex-shrink: 0;
}
.nge-chat-strip[data-v-1ed9098a]:active { cursor: grabbing;
}
.nge-chat-strip-dot[data-v-1ed9098a] {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #444;
  flex-shrink: 0;
}
.nge-chat-strip-dot--on[data-v-1ed9098a] {
  background: #0fb18b;
  box-shadow: 0 0 4px rgba(15, 177, 139, 0.5);
}
.nge-chat-strip-label[data-v-1ed9098a] {
  font-size: 10px;
  color: #667;
  font-weight: 600;
  letter-spacing: 0.3px;
}
.nge-chat-strip-unread[data-v-1ed9098a] {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4a9eff;
  box-shadow: 0 0 6px rgba(74, 158, 255, 0.6);
  flex-shrink: 0;
  animation: nge-chat-unread-pulse-1ed9098a 2s ease-in-out infinite;
}
@keyframes nge-chat-unread-pulse-1ed9098a {
0%, 100% { opacity: 1;
}
50% { opacity: 0.4;
}
}
.nge-chat-strip-spacer[data-v-1ed9098a] { flex: 1;
}
.nge-chat-strip-btn[data-v-1ed9098a] {
  background: none;
  border: none;
  color: #556;
  cursor: pointer;
  line-height: 1;
  transition: color 0.12s, background 0.12s;
  border-radius: 3px;
}
.nge-chat-strip-btn[data-v-1ed9098a]:hover { color: #ccc; background: rgba(255, 255, 255, 0.06);
}
.nge-chat-collapse-btn[data-v-1ed9098a] {
  font-size: 11px;
  padding: 2px 5px;
}
.nge-chat-close-btn[data-v-1ed9098a] {
  font-size: 16px;
  padding: 0 5px;
  font-weight: 300;
}
.nge-chat-close-btn[data-v-1ed9098a]:hover { color: #ff6b6b; background: rgba(255, 80, 80, 0.08);
}

/* ── Messages wrapper with fade ── */
.nge-chat-messages-wrap[data-v-1ed9098a] {
  flex: 1;
  position: relative;
  min-height: 0;
  overflow: hidden;
}

/* Background gradient: opaque at bottom (contrast for text) → transparent at top */
.nge-chat-fade[data-v-1ed9098a] {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 100%;
  background: linear-gradient(to top, rgba(8,10,20,0.88) 0%, rgba(8,10,20,0.65) 30%, rgba(8,10,20,0.3) 60%, transparent 100%);
  pointer-events: none;
  z-index: 1;
}
.nge-chat-messages[data-v-1ed9098a] {
  height: 100%;
  overflow-y: auto;
  display: flex;
  flex-direction: column-reverse;
  padding: 2px 8px;
  position: relative;
  z-index: 2;
}
.nge-chat-messages[data-v-1ed9098a]::-webkit-scrollbar { width: 2px;
}
.nge-chat-messages[data-v-1ed9098a]::-webkit-scrollbar-track { background: transparent;
}
.nge-chat-messages[data-v-1ed9098a]::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.08); border-radius: 2px;
}
.nge-chat-messages-inner[data-v-1ed9098a] {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ── Message line — inline name + text ── */
.nge-chat-msg[data-v-1ed9098a] {
  padding: 3px 4px;
  line-height: 1.45;
  font-size: 14.5px;
}
.nge-chat-msg[data-v-1ed9098a]:hover { background: rgba(255, 255, 255, 0.03); border-radius: 3px;
}
.nge-chat-msg-time[data-v-1ed9098a] {
  font-size: 11px;
  color: #556;
  margin-right: 5px;
  flex-shrink: 0;
}
.nge-chat-msg:hover .nge-chat-msg-time[data-v-1ed9098a] { color: #889;
}
.nge-chat-msg-trophy[data-v-1ed9098a] { font-size: 12px; margin-right: 1px;
}
.nge-chat-msg-name[data-v-1ed9098a] {
  font-weight: 600;
  font-size: 14.5px;
  margin-right: 4px;
}
.nge-chat-msg-name--clickable[data-v-1ed9098a] {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  font-weight: 600;
  font-size: 14.5px;
  transition: opacity 0.15s;
}
.nge-chat-msg-name--clickable[data-v-1ed9098a]:hover {
  opacity: 0.8;
  text-decoration: underline;
}
.nge-chat-msg-text[data-v-1ed9098a] {
  color: #b0b8c8;
}
.nge-chat-link[data-v-1ed9098a] {
  color: #4a9eff;
  text-decoration: none;
  word-break: break-all;
  font-size: 14.5px;
}
.nge-chat-link[data-v-1ed9098a]:hover { text-decoration: underline;
}

/* Shared segment id: click the id to jump, click ⧉ to copy — and the id text
   itself is selectable so it can be dragged out / copied manually. It used to
   be a <button>, which browsers don't let you select text inside, so a shared
   ID could neither be copied nor (see loadSegment) actually jumped to. */
.nge-chat-seg-chip[data-v-1ed9098a] {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  background: rgba(0, 220, 120, 0.1);
  border: 1px solid rgba(0, 220, 120, 0.25);
  border-radius: 4px;
  transition: background 0.15s, border-color 0.15s;
}
.nge-chat-seg-chip[data-v-1ed9098a]:hover {
  background: rgba(0, 220, 120, 0.2);
  border-color: rgba(0, 220, 120, 0.4);
}
.nge-chat-seg-link[data-v-1ed9098a] {
  color: #80ffc0;
  padding: 1px 2px 1px 6px;
  font-size: 12px;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  cursor: pointer;
  /* The chat body sets user-select: none; re-enable it here so the id can be
     highlighted and copied by hand. */
  user-select: text;
  -webkit-user-select: text;
}
.nge-chat-seg-link[data-v-1ed9098a]:focus-visible {
  outline: 1px solid rgba(0, 220, 120, 0.7);
  outline-offset: 1px;
}
.nge-chat-seg-copy[data-v-1ed9098a] {
  background: none;
  border: none;
  color: rgba(128, 255, 192, 0.6);
  cursor: pointer;
  font-size: 11px;
  line-height: 1;
  padding: 2px 5px 2px 2px;
}
.nge-chat-seg-copy[data-v-1ed9098a]:hover { color: #80ffc0; background: none;
}
/* Announcement message — visually distinct from conversation so it reads as
   something actionable rather than someone talking. */
.nge-chat-announce[data-v-1ed9098a] {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  background: rgba(74, 158, 255, 0.09);
  border-left: 2px solid rgba(74, 158, 255, 0.55);
  border-radius: 4px;
  padding: 3px 6px;
  margin: 2px 0;
  transition: background 0.15s;
}
.nge-chat-announce[data-v-1ed9098a]:hover { background: rgba(74, 158, 255, 0.18);
}
.nge-chat-announce-text[data-v-1ed9098a] { flex: 1; color: #d6e6ff;
}
.nge-chat-announce-cta[data-v-1ed9098a] {
  flex: 0 0 auto;
  font-size: 10.5px;
  color: rgba(150, 190, 245, 0.9);
  white-space: nowrap;
}

/* @mention: click to open that person's profile. Highlighted more strongly
   when it's you being mentioned, so it's noticeable in a busy channel. */
.nge-chat-mention[data-v-1ed9098a] {
  color: #9db8ff;
  background: rgba(74, 158, 255, 0.12);
  border-radius: 3px;
  padding: 0 3px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.nge-chat-mention[data-v-1ed9098a]:hover { background: rgba(74, 158, 255, 0.25); color: #cfe0ff;
}
.nge-chat-mention--me[data-v-1ed9098a] {
  color: #ffe6a8;
  background: rgba(245, 166, 35, 0.2);
  font-weight: 600;
}
.nge-chat-mention--me[data-v-1ed9098a]:hover { background: rgba(245, 166, 35, 0.32); color: #fff2cf;
}
.nge-chat-mention[data-v-1ed9098a]:focus-visible { outline: 1px solid rgba(74, 158, 255, 0.7); outline-offset: 1px;
}

/* Which segmentation the id belongs to — a bare root ID is ambiguous without it. */
.nge-chat-seg-ds[data-v-1ed9098a] {
  color: rgba(128, 255, 192, 0.55);
  font-size: 10px;
  padding: 0 2px;
  white-space: nowrap;
  user-select: none;
}
.nge-chat-segwarn[data-v-1ed9098a] {
  margin: 4px 6px;
  padding: 7px 9px;
  background: rgba(245, 166, 35, 0.1);
  border: 1px solid rgba(245, 166, 35, 0.3);
  border-radius: 6px;
  font-size: 11.5px;
  color: #f0d0a0;
}
.nge-chat-segwarn-text[data-v-1ed9098a] { line-height: 1.35;
}
.nge-chat-segwarn-text strong[data-v-1ed9098a] { color: #ffd9a3; font-weight: 600;
}
.nge-chat-segwarn-actions[data-v-1ed9098a] { display: flex; gap: 6px; margin-top: 6px;
}
.nge-chat-segwarn-go[data-v-1ed9098a],
.nge-chat-segwarn-no[data-v-1ed9098a] {
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 5px;
  padding: 2px 8px;
  font-size: 11px;
  cursor: pointer;
}
.nge-chat-segwarn-go[data-v-1ed9098a] { color: #ffc98a; border-color: rgba(245, 166, 35, 0.5);
}
.nge-chat-segwarn-go[data-v-1ed9098a]:hover { background: rgba(245, 166, 35, 0.18);
}
.nge-chat-segwarn-no[data-v-1ed9098a] { color: #99a;
}
.nge-chat-segwarn-no[data-v-1ed9098a]:hover { background: rgba(255, 255, 255, 0.06);
}

/* System messages */
.nge-chat-sys[data-v-1ed9098a] {
  font-size: 12.5px;
  color: #6a7282;
  font-style: italic;
  padding: 1px 4px;
}
.nge-chat-sys--warn[data-v-1ed9098a] { color: #c08030;
}

/* Time separator */
.nge-chat-time-sep[data-v-1ed9098a] {
  text-align: center;
  padding: 3px 0;
}
.nge-chat-time-sep span[data-v-1ed9098a] {
  font-size: 11.5px;
  color: #6a7282;
  padding: 0 6px;
}

/* New messages banner */
.nge-chat-new-banner[data-v-1ed9098a] {
  position: absolute;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(74, 158, 255, 0.8);
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 8px;
  cursor: pointer;
  z-index: 5;
}
.nge-chat-new-banner[data-v-1ed9098a]:hover { background: rgba(74, 158, 255, 1);
}
.nge-chat-banner-enter-active[data-v-1ed9098a] { transition: opacity 0.15s;
}
.nge-chat-banner-leave-active[data-v-1ed9098a] { transition: opacity 0.12s;
}
.nge-chat-banner-enter-from[data-v-1ed9098a],
.nge-chat-banner-leave-to[data-v-1ed9098a] { opacity: 0;
}

/* ── Input ── */
.nge-chat-input-wrap[data-v-1ed9098a] {
  padding: 4px 4px;
  flex-shrink: 0;
  background: rgba(8, 10, 20, 0.92);
  border-top: 1px solid rgba(100, 180, 255, 0.08);
}
.nge-chat-input[data-v-1ed9098a] {
  width: 100%;
  background: rgba(20, 24, 40, 0.9);
  border: 1px solid rgba(100, 180, 255, 0.15);
  border-radius: 4px;
  padding: 6px 8px;
  color: #e0e4ec;
  font-size: 14.5px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.12s;
  box-sizing: border-box;
}
.nge-chat-input[data-v-1ed9098a]:focus { border-color: rgba(74, 158, 255, 0.3);
}
.nge-chat-input[data-v-1ed9098a]::placeholder { color: #556;
}
.nge-chat-input[data-v-1ed9098a]:disabled { opacity: 0.3;
}

/* Empty state */
.nge-chat-empty[data-v-1ed9098a] {
  text-align: center;
  padding: 20px 8px;
  color: #889;
  font-size: 13.5px;
  font-style: italic;
}
