/* ── Transition ── */
/* The panel's own ngeNotifMaterialize animation drives the entrance, so the Vue
   transition only fades the backdrop in and animates the leave (no enter
   transform on the panel, or the two fight). */
.nge-notif-detail-enter-active[data-v-17795884] { transition: opacity 0.25s ease;
}
.nge-notif-detail-leave-active[data-v-17795884] { transition: opacity 0.18s ease;
}
.nge-notif-detail-leave-active .nge-notif-detail[data-v-17795884] { transition: transform 0.18s ease, opacity 0.18s ease, filter 0.18s ease;
}
.nge-notif-detail-enter-from[data-v-17795884] { opacity: 0;
}
.nge-notif-detail-leave-to[data-v-17795884] { opacity: 0;
}
.nge-notif-detail-leave-to .nge-notif-detail[data-v-17795884] { transform: scale(0.97); opacity: 0; filter: blur(6px) brightness(1.6);
}

