
.nge-guide[data-v-1b603618] {
  position: fixed;
  /* `bottom` is raised inline (see SPLIT_MERGE_CLEARANCE) while a graphene
     tool is open so the full-width split/merge banner can't cover the dock. */
  transition: bottom 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  bottom: 36px;
  right: 8px;
  width: 340px;
  max-width: calc(100vw - 16px);
  height: 460px;
  max-height: calc(100vh - 80px);
  z-index: 9001;
  display: flex;
  flex-direction: column;
  background: rgba(6, 10, 20, 0.92);
  border-radius: 8px;
  border: 1px solid rgba(74, 158, 255, 0.18);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  font-family: 'Inter', 'Roboto', sans-serif;
  color: #dbe4f0;
}

/* ── Resize handles ── */
.nge-guide-resize[data-v-1b603618] { position: absolute; z-index: 20;
}
.nge-guide-resize--corner[data-v-1b603618] {
  top: 0; left: 0; width: 16px; height: 16px; cursor: nwse-resize;
}
.nge-guide-resize--corner[data-v-1b603618]::after {
  content: ''; position: absolute; top: 4px; left: 4px;
  width: 6px; height: 6px;
  border-top: 2px solid rgba(74, 158, 255, 0.3);
  border-left: 2px solid rgba(74, 158, 255, 0.3);
  border-radius: 1px; transition: border-color 0.15s;
}
.nge-guide-resize--corner[data-v-1b603618]:hover::after { border-color: rgba(74, 158, 255, 0.75);
}
.nge-guide-resize--top[data-v-1b603618] {
  top: 0; left: 16px; right: 0; height: 5px; cursor: ns-resize;
}
.nge-guide-resize--top[data-v-1b603618]:hover { background: rgba(74, 158, 255, 0.18);
}
.nge-guide-resize--left[data-v-1b603618] {
  top: 16px; left: 0; width: 5px; bottom: 0; cursor: ew-resize;
}
.nge-guide-resize--left[data-v-1b603618]:hover { background: rgba(74, 158, 255, 0.18);
}
.nge-guide-header[data-v-1b603618] {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 10px;
  border-bottom: 1px solid rgba(74, 158, 255, 0.12);
  flex-shrink: 0;
}
.nge-guide-dot[data-v-1b603618] {
  width: 7px; height: 7px; border-radius: 50%;
  background: #0fb18b;
  box-shadow: 0 0 6px rgba(15, 177, 139, 0.6);
}
/* Nurro avatar (the guide's profile pic) */
.nge-guide-avatar[data-v-1b603618] {
  position: relative;
  width: 30px; height: 30px;
  flex-shrink: 0;
  border-radius: 50%;
  background-color: #0e1830;
  background-repeat: no-repeat;
  background-size: 200%;
  background-position: 47% 16%;   /* zoomed onto Nurro's face + magnifying glass */
  border: 1px solid rgba(74, 158, 255, 0.35);
  box-shadow: 0 0 8px rgba(74, 158, 255, 0.2);
}
.nge-guide-status[data-v-1b603618] {
  position: absolute; right: -1px; bottom: -1px;
  width: 8px; height: 8px; border-radius: 50%;
  background: #0fb18b;
  box-shadow: 0 0 5px rgba(15, 177, 139, 0.7);
  border: 1.5px solid rgba(6, 10, 20, 0.95);
}
.nge-guide-title[data-v-1b603618] {
  font-size: 12px; font-weight: 600; letter-spacing: 0.02em;
  color: #cfe0f5; flex: 1;
}
.nge-guide-close[data-v-1b603618] {
  background: none; border: none; color: #6b7a90; cursor: pointer;
  font-size: 12px; padding: 2px 5px; border-radius: 4px;
}
.nge-guide-close[data-v-1b603618]:hover { color: #cfe0f5; background: rgba(255,255,255,0.06);
}
.nge-guide-scroll[data-v-1b603618] {
  flex: 1; overflow-y: auto; padding: 10px;
  display: flex; flex-direction: column; gap: 8px;
  /* Firefox */
  scrollbar-width: thin;
  scrollbar-color: rgba(74, 158, 255, 0.35) transparent;
}
/* Chrome / Edge / Safari */
.nge-guide-scroll[data-v-1b603618]::-webkit-scrollbar { width: 8px;
}
.nge-guide-scroll[data-v-1b603618]::-webkit-scrollbar-track { background: transparent;
}
.nge-guide-scroll[data-v-1b603618]::-webkit-scrollbar-thumb {
  background: rgba(74, 158, 255, 0.3);
  border-radius: 4px;
}
.nge-guide-scroll[data-v-1b603618]::-webkit-scrollbar-thumb:hover {
  background: rgba(74, 158, 255, 0.5);
}
.nge-guide-empty[data-v-1b603618] { display: flex; flex-direction: column; gap: 6px;
}
.nge-guide-hi[data-v-1b603618] { font-size: 12.5px; color: #9fb2c8; line-height: 1.5; margin: 2px 0 6px;
}
.nge-guide-quest[data-v-1b603618] {
  margin-top: 12px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.nge-guide-quest-label[data-v-1b603618] {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.4);
}
.nge-guide-quest-link[data-v-1b603618] {
  font-size: 11.5px;
  color: rgba(100, 200, 255, 0.85);
  text-decoration: none;
  padding: 2px 8px;
  border: 1px solid rgba(100, 200, 255, 0.2);
  border-radius: 10px;
  white-space: nowrap;
  transition: background 0.12s ease, color 0.12s ease;
}
.nge-guide-quest-link[data-v-1b603618]:hover {
  background: rgba(100, 200, 255, 0.12);
  color: #fff;
}
.nge-guide-suggest[data-v-1b603618] {
  text-align: left; background: rgba(74, 158, 255, 0.08);
  border: 1px solid rgba(74, 158, 255, 0.16); color: #bcd2ee;
  border-radius: 6px; padding: 7px 9px; font-size: 12px; cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}
.nge-guide-suggest[data-v-1b603618]:hover { background: rgba(74, 158, 255, 0.16); border-color: rgba(74, 158, 255, 0.35);
}
.nge-guide-msg[data-v-1b603618] { display: flex;
}
.nge-guide-msg--user[data-v-1b603618] { justify-content: flex-end;
}
.nge-guide-msg--bot[data-v-1b603618] { justify-content: flex-start;
}
.nge-guide-bubble[data-v-1b603618] {
  max-width: 85%; padding: 7px 10px; border-radius: 10px;
  font-size: 12.5px; line-height: 1.5; word-wrap: break-word;
}
.nge-guide-bubble--user[data-v-1b603618] {
  background: rgba(74, 158, 255, 0.22); color: #eaf2ff;
  border-bottom-right-radius: 3px;
}
.nge-guide-bubble--bot[data-v-1b603618] {
  background: rgba(255, 255, 255, 0.06); color: #dbe4f0;
  border-bottom-left-radius: 3px;
}
.nge-guide-bubble--bot[data-v-1b603618] p { margin: 0 0 6px;
}
.nge-guide-bubble--bot[data-v-1b603618] p:last-child { margin-bottom: 0;
}
.nge-guide-bubble--bot[data-v-1b603618] code {
  background: rgba(0,0,0,0.35); padding: 1px 4px; border-radius: 3px;
  font-size: 11.5px;
}
.nge-guide-bubble--bot[data-v-1b603618] a { color: #6fb2ff;
}
.nge-guide-bubble--bot[data-v-1b603618] ul, .nge-guide-bubble--bot[data-v-1b603618] ol { margin: 4px 0; padding-left: 18px;
}

/* ── Feedback controls ── */
.nge-guide-botwrap[data-v-1b603618] { display: flex; flex-direction: column; max-width: 85%;
}
.nge-guide-botwrap .nge-guide-bubble[data-v-1b603618] { max-width: 100%;
}
.nge-guide-fb[data-v-1b603618] { display: flex; align-items: center; gap: 4px; margin: 3px 2px 0; min-height: 20px;
}
.nge-guide-fb-btn[data-v-1b603618] {
  background: none; border: none; cursor: pointer; font-size: 13px;
  line-height: 1; padding: 2px 4px; border-radius: 4px; opacity: 0.5;
  filter: grayscale(0.4); transition: opacity 0.12s, background 0.12s, filter 0.12s;
}
.nge-guide-fb-btn[data-v-1b603618]:hover { opacity: 1; filter: none; background: rgba(255, 255, 255, 0.07);
}
.nge-guide-fb-thanks[data-v-1b603618] { font-size: 10.5px; color: #7c8ba0;
}
.nge-guide-correct[data-v-1b603618] { display: flex; flex-direction: column; gap: 5px; margin-top: 4px; width: 100%;
}
.nge-guide-correct-input[data-v-1b603618] {
  resize: none; background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(74, 158, 255, 0.25); border-radius: 6px;
  color: #eaf2ff; font-size: 12px; padding: 6px 8px; font-family: inherit; line-height: 1.4;
}
.nge-guide-correct-input[data-v-1b603618]:focus { outline: none; border-color: rgba(74, 158, 255, 0.5);
}
.nge-guide-correct-actions[data-v-1b603618] { display: flex; gap: 6px;
}
.nge-guide-correct-send[data-v-1b603618] {
  background: rgba(74, 158, 255, 0.85); color: #fff; border: none;
  border-radius: 5px; padding: 4px 10px; font-size: 11.5px; font-weight: 600; cursor: pointer;
}
.nge-guide-correct-send[data-v-1b603618]:hover { background: rgba(74, 158, 255, 1);
}
.nge-guide-correct-skip[data-v-1b603618] {
  background: none; color: #8b9ab0; border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 5px; padding: 4px 10px; font-size: 11.5px; cursor: pointer;
}
.nge-guide-correct-skip[data-v-1b603618]:hover { color: #cfe0f5; border-color: rgba(255, 255, 255, 0.25);
}
.nge-guide-typing[data-v-1b603618] { display: flex; gap: 4px; align-items: center;
}
.nge-guide-typing span[data-v-1b603618] {
  width: 6px; height: 6px; border-radius: 50%; background: #6b7a90;
  animation: nge-guide-blink-1b603618 1.2s infinite ease-in-out;
}
.nge-guide-typing span[data-v-1b603618]:nth-child(2) { animation-delay: 0.2s;
}
.nge-guide-typing span[data-v-1b603618]:nth-child(3) { animation-delay: 0.4s;
}
@keyframes nge-guide-blink-1b603618 {
0%, 80%, 100% { opacity: 0.25;
}
40% { opacity: 1;
}
}

/* Instant command matches, shown above the input. Visually distinct from chat
   so it reads as "this will run", not "this is a reply". */
.nge-guide-cmds[data-v-1b603618] {
  border-top: 1px solid rgba(74, 158, 255, 0.12);
  padding: 6px 6px 2px;
  max-height: 210px;
  overflow-y: auto;
  flex-shrink: 0;
}
.nge-guide-cmds-hint[data-v-1b603618] {
  font-size: 9.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(160, 175, 200, 0.65);
  padding: 2px 6px 4px;
}
.nge-guide-cmd[data-v-1b603618] {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: 6px;
  background: none;
  color: #cfdcef;
  font-size: 12.5px;
  text-align: left;
  cursor: pointer;
}
.nge-guide-cmd--sel[data-v-1b603618] { background: rgba(74, 158, 255, 0.16); color: #e6f0ff;
}
.nge-guide-cmd-icon[data-v-1b603618] { flex: 0 0 auto; font-size: 13px;
}
.nge-guide-cmd-label[data-v-1b603618] { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.nge-guide-cmd-key[data-v-1b603618] {
  flex: 0 0 auto;
  font-family: 'Consolas', 'Monaco', monospace;
  font-size: 10.5px;
  color: rgba(160, 175, 200, 0.8);
  background: rgba(255, 255, 255, 0.06);
  border-radius: 4px;
  padding: 1px 5px;
}
.nge-guide-inputrow[data-v-1b603618] {
  display: flex; align-items: flex-end; gap: 6px;
  padding: 8px; border-top: 1px solid rgba(74, 158, 255, 0.12);
  flex-shrink: 0;
}
.nge-guide-input[data-v-1b603618] {
  flex: 1; resize: none; max-height: 90px;
  background: rgba(255,255,255,0.05); border: 1px solid rgba(74,158,255,0.16);
  border-radius: 6px; color: #eaf2ff; font-size: 12.5px; padding: 7px 9px;
  font-family: inherit; line-height: 1.4;
}
.nge-guide-input[data-v-1b603618]:focus { outline: none; border-color: rgba(74,158,255,0.45);
}
.nge-guide-input[data-v-1b603618] { scrollbar-width: thin; scrollbar-color: rgba(74, 158, 255, 0.35) transparent;
}
.nge-guide-input[data-v-1b603618]::-webkit-scrollbar { width: 8px;
}
.nge-guide-input[data-v-1b603618]::-webkit-scrollbar-track { background: transparent;
}
.nge-guide-input[data-v-1b603618]::-webkit-scrollbar-thumb { background: rgba(74, 158, 255, 0.3); border-radius: 4px;
}
.nge-guide-send[data-v-1b603618] {
  flex-shrink: 0; width: 30px; height: 30px; border-radius: 6px;
  background: rgba(74, 158, 255, 0.85); color: #fff; border: none;
  cursor: pointer; font-size: 15px; font-weight: 700;
}
.nge-guide-send[data-v-1b603618]:disabled { background: rgba(74,158,255,0.25); cursor: default;
}
.nge-guide-send[data-v-1b603618]:not(:disabled):hover { background: rgba(74, 158, 255, 1);
}
